esqlQuery.esql:
// Alert when any model's p99 latency exceeds a threshold in milliseconds.
// Default: 5000ms (5 seconds). Adjust per your SLO.
// Groups by model, which is always present with the default dimensions.
// To group by provider instead, add 'provider' to the performance stream dimensions.
FROM metrics-openrouter.performance-*
| WHERE openrouter.performance.p99_latency IS NOT NULL AND openrouter.performance.model IS NOT NULL
| STATS max_p99_ms = MAX(openrouter.performance.p99_latency) BY openrouter.performance.model
| WHERE max_p99_ms > 5000
| SORT max_p99_ms DESC
